import pytest

# Define the function to parse, to avoid dependency issues in the tests

def parse(original_string):
    return original_string.split('\n')

# Function to be tested

def add_to_line(comments, original_string='', removed=False, comment_prefix=''):
    if removed:
        return parse(original_string)[0]
    if not comments:
        return original_string
    unique_comments = []
    for comment in comments:
        if comment not in unique_comments:
            unique_comments.append(comment)
    return f"{parse(original_string)[0]}{comment_prefix} {'; '.join(unique_comments)}"

# Test cases

def test_add_to_line_with_comments():
    assert add_to_line(['comment1', 'comment2'], 'base string', False) == 'base string comment1; comment2'

def test_add_to_line_without_comments():
    assert add_to_line([], 'base string', False) == 'base string'

def test_add_to_line_when_removed():
    assert add_to_line(['comment1'], 'base string with comments\nsecond line', True) == 'base string with comments'

def test_add_to_line_duplicate_comments():
    assert add_to_line(['comment1', 'comment1'], 'base string', False) == 'base string comment1'

def test_add_to_line_with_prefix():
    assert add_to_line(['comment1'], 'base string', False, '# ') == 'base string # comment1'

